DO $$ DECLARE f text;d text;BEGIN FOREACH f IN ARRAY ARRAY['public.finance_fx_payment_prepare(uuid,text,uuid,date,numeric,numeric,uuid,text)','public.finance_fx_revaluation_preview(uuid,date)','public.finance_fx_draft_finish(uuid,public.finance_entry_drafts,uuid)'] LOOP SELECT pg_get_functiondef(f::regprocedure) INTO d;d:=replace(d,'source_id=ident::text','source_id=ident');d:=replace(d,'source_id=invoices.id::text','source_id=invoices.id');d:=replace(d,'''adjustment'',q.id::text','''adjustment'',q.id');EXECUTE d;END LOOP;END $$;